    "code": "الف-1-6-5",
    "_std": "الف-1-6",
    "statement": "براساس تاکید وزارت بهداشت در جمع آوری گزارش وقایع ناخواسته در سطح ملی در موارد 28 گانه دستورالعمل مزبور است. این امر به معنی عدم نیاز به گزارش، تحلیل ریش‌های و مدیریت سایر وقایع ناخواسته درمان نیست و بایستی تمامی موارد وقایع ناخواسته ناشی از ارائه خدمات/ مراقبت سلامت شناسایی، پیش‌گیری و مدیریت شوند. اجرای دستورالعمل ابلاغی وقایع ناخواسته درمانی لازم االجرا می‌باشد. تیم رهبری و مدیریت با اتخاذ رویکرد عاری از سرزنش نابجا، منطبق بر نگرش سیستمیک و فرهنگ منصفانه1، گزارش‌دهی وقایع ناخواسته درمان را ترویج می‌نماید2. در فرهنگ منصفانه، این موضوع در می‌گردد که کارکنان حرف‌های واجد صلاحیت ممکن است دچار اشتباه شوند و حتی ممکن است رفتار‌های متفاوت با هنجار‌های سازمانی از خود بروز دهند ولی بیمباالتی‌ها قابل پذیرش و تحمل نیست. Just Culture 1 2 برای شرح فرهنگ ایمنی بیمار به توضیحات سنجه الف-1-6-9 مراجعه گردد. الف-1-6-5 وقایع ناخواسته ناشی از ارائه خدمات / مراقبت سلامت، شناسایی، پیش‌گیری و مدیریت می‌شوند.",
